schemas.schema-01-systematic.prisma:
/// Discussion Board Channels - Implements the system's multi-board partitioning requirement from the introduction and purpose documentation.
///
/// This model represents distinct logical channels within the overall discussion platform, each potentially covering a broad topic area or serving as an umbrella for more granular discussion boards. Each channel groups related sections or boards, allowing for flexible configuration, discoverability, and moderation boundaries.
///
/// Maintains 3NF by storing only channel-specific atomic data. For example, a platform could have channels such as 'Politics', 'Economics', each of which houses multiple sub-boards or sections.
///
/// Key relationships: Referenced by sections and boards for hierarchical organization.
/// Special behaviors: Supports soft deletion for audit trail, and can be toggled as visible or hidden in global navigation.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_channels {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each discussion channel.
  id String @id @db.Uuid

  /// Channel name - Implements the naming structure requirement for top-level forum partitioning. Stores a unique, human-readable identifier for this channel (e.g., 'Politics', 'Economics'). Ensures normalization by separating channel name from any derived or display content. For example, 'International Affairs'.
  name String

  /// Channel description - Implements the metadata/context requirement. Provides a brief explanation of what the channel covers, aiding user navigation and discoverability. Maintains normalization by not mixing this with posts or boards' content. For example, 'Debate topics on domestic and world politics.'.
  description String?

  /// Creation timestamp - Implements the audit/compliance requirement. Records when the channel was established. For example, '2023-11-21T14:00:00Z'.
  created_at DateTime @db.Timestamptz

  /// Update timestamp - Audit/compliance requirement; indicates the last time channel info was modified. Enables efficient auditing and change detection.
  updated_at DateTime @db.Timestamptz

  /// Deletion timestamp (for soft-delete) - Enables reversible/historical auditing per policy requirements. Null if not deleted. Ensures normalization by not removing records outright. For example, '2024-01-01T09:00:00Z' or null.
  deleted_at DateTime? @db.Timestamptz

  /// Visibility flag - Implements platform-wide configuration requirement. If false, channel is hidden from general navigation. Ensures atomic control over channel's appearance. For example, false when shutting down a channel for policy reasons.
  is_visible Boolean

  //----
  // RELATIONS
  //----
  discussionboard_sections discussionboard_sections[]

  @@unique([name])
  @@index([created_at])
}

/// Discussion Board Sections - Implements the hierarchical board structure requirement from the introduction and purpose and organizational requirements.
///
/// Each section represents a further subdivision within a channel, typically covering a subtopic or grouping related boards. Normalized to contain only atomic section-level data. Used to organize boards and topics for intuitive navigation and delegated moderation.
///
/// For example, the 'Economics' channel may contain the sections 'Macroeconomics', 'Microeconomics', and 'Policy'.
///
/// Key relationships: Contains a foreign key reference to its parent channel. Referenced by boards for sectional grouping.
/// Special behaviors: Supports position ordering for display, and soft deletion for recoverability.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_sections {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each discussion section.
  id String @id @db.Uuid

  /// Parent channel's {@link discussionboard_channels.id}. Establishes the section's top-level grouping for platform navigation and moderation boundaries.
  discussionboard_channel_id String @db.Uuid

  /// Section name - Implements the requirement for sub-board labeling. Human-readable label for the section (e.g., 'Macroeconomics'). Distinct per channel. Maintains normalization by separating label from display or content data.
  name String

  /// Section description - Supports metadata/context requirements. Provides additional information about the section's focus. Kept nullable for brevity or when not required by policy. For example, 'All discussions related to global economic trends.'
  description String?

  /// Section ordering position - Implements display order requirements for UI. Stored as an integer; allows reordering without changing IDs.
  position Int @db.Integer

  /// Creation timestamp - For audit/compliance tracking. Records the date/time the section was created.
  created_at DateTime @db.Timestamptz

  /// Update timestamp - Last modification to section metadata. For change detection and audit trails.
  updated_at DateTime @db.Timestamptz

  /// Soft-deletion timestamp. Null if not deleted, otherwise indicates when section was hidden for policy/compliance purposes.
  deleted_at DateTime? @db.Timestamptz

  /// Visibility flag - Determines if section is displayed in navigation/search. Set false to temporarily hide. Implements atomic access and policy toggling requirement.
  is_visible Boolean

  //----
  // RELATIONS
  //----
  section_channel discussionboard_channels @relation(fields: [discussionboard_channel_id], references: [id], onDelete: Cascade)

  discussionboard_settings discussionboard_settings[]

  @@unique([discussionboard_channel_id, name])
  @@index([discussionboard_channel_id])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// System Configuration Registry - Implements the platform-wide settings/audit requirements.
///
/// Contains all global key-value configuration entries for the discussion board system (e.g., maintenance mode, password policy, default board behaviors). Fully normalized to ensure each config setting is atomic. Business logic implementation reads keys/values for runtime system behavior.
///
/// Key relationships: No foreign keys—self-contained for architectural separation.
/// Special behaviors: Supports type safety enforcement and versioned auditing.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_configurations {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each configuration record.
  id String @id @db.Uuid

  /// Configuration key - Implements requirement for named config registry entries; e.g., 'maintenance_mode', 'max_post_length'. Ensures each config parameter is individually addressable. Unique for the schema.
  config_key String

  /// Configuration value - Stores actual config data, always as a string for normalization across boolean, numeric, text settings. For example: 'true', '2048', 'Welcome to the board!'.
  config_value String

  /// Value type - Implements explicit type tracking requirement; e.g., 'boolean', 'int', 'string', 'datetime'. Separates data from type for normalization and safety.
  value_type String

  /// Config description - Documents the purpose/usage of each config; assists admins and devs. For example, 'Enables or disables new user signups.'. Not shown to regular members.
  description String?

  /// Creation timestamp for the configuration entry. Supports auditing and compliance logging.
  created_at DateTime @db.Timestamptz

  /// Last updated timestamp for the entry. Aids in config change tracking.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([config_key])
  @@index([value_type])
  @@index([created_at])
}

/// System Audit Log - Implements the audit/compliance logging requirement.
///
/// Stores all significant system-level and user-led actions related to policy enforcement, administrative changes, and moderation outcomes, as required by operational and regulatory guidelines. Keeps normalized, atomic records for actions, actors, and metadata. Used for retrospective investigations, compliance audits, and appeals analysis.
///
/// Key relationships: Optionally references member/admin records in Actors component for actor_id.
/// Special behaviors: NEVER soft-delete; logs are permanent as required by compliance. Large volume/readonly design for performance.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_audit_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each audit log record.
  id String @id @db.Uuid

  /// Optional reference to actor (member/moderator/admin) who performed the action. Links to discussionboard_members, discussionboard_moderators, or discussionboard_admins in Actors component. Null for system or anonymous events. Ensures normalization by referencing, never storing actor names.
  actor_id String? @db.Uuid

  /// Type of action logged (e.g., 'POST_EDIT', 'USER_BAN', 'CONFIG_UPDATE', 'REPORT_ESCALATE'). Implements detailed event catalog for traceability. Normalized string values.
  action_type String

  /// Scope of the affected resource (e.g., 'post', 'comment', 'user', 'system'). Supports multi-entity audit coverage. Maintains normalization by not embedding resource details here.
  action_scope String

  /// ID of the affected resource (may refer to post, comment, config, etc. Schema-enforced by scope and audit logic). Atomic, polymorphic reference. Null if not applicable (e.g., system-level events).
  target_id String? @db.Uuid

  /// Optional additional context/parameters for this log entry in serialized (e.g., JSON) format. For example, change diff, before/after values. Maintains normalization by never duplicating structural data. Kept as string for DB-agnosticism.
  metadata String?

  /// Creation timestamp for the audit log event. Immutable; required for all entries. Forms the timeline basis for compliance reporting.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  auditlog_actor discussionboard_members? @relation(fields: [actor_id], references: [id], onDelete: Cascade)

  @@index([actor_id])

  @@index([action_type])
  @@index([action_scope])
  @@index([created_at])
}

/// Lightweight System Settings - Implements per-section or user-overrideable parameters for the platform.
///
/// Configured as a separate table from configurations for localized, frequently-overridden, or member-facing settings (e.g., default notification preferences, custom display toggles). Normalized to link each setting either globally or to a logical owner (e.g., section, member).
///
/// Key relationships: May reference sections, members, or be system-global.
/// Special behaviors: Settings can be inherited or overridden per the type/owner.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_settings {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each settings record.
  id String @id @db.Uuid

  /// Optional reference to a section ({@link discussionboard_sections.id}) for section-level settings. Null for global/system settings. Ensures normalization by not repeating setting values per section without context.
  section_id String? @db.Uuid

  /// Settings key - Unique identifier for this parameter; e.g., 'default_sort', 'theme_mode'. Implements settings registry requirement; atomic per entry.
  setting_key String

  /// Settings value - String representation of the current setting. Maintains normalization without mixing with configuration data.
  setting_value String

  /// Owner type - Implements scope-separation requirement. Defines if this setting is global, per-section, or per-member; e.g., 'global', 'section', 'member'. Required for scope enforcement.
  owner_type String

  /// Optional reference to a board member or other owner. Null for global or section-scoped settings. Normalized for privacy and audit reasons.
  owner_id String? @db.Uuid

  /// Detailed description of this setting, for admin UI or developer documentation. Not displayed to general members. For example, 'Sets the default sort order for new posts in this section.'
  description String?

  /// Timestamp when the setting entry was created. Required for audit and configuration traceability.
  created_at DateTime @db.Timestamptz

  /// Timestamp for last modification to this record. Aids auditing and change notifications.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  settings_section discussionboard_sections? @relation(fields: [section_id], references: [id], onDelete: Cascade)

  @@unique([setting_key, owner_type, owner_id])
  @@index([section_id])
  @@index([owner_type])
  @@index([created_at])
  @@index([setting_key(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-02-actors.prisma:
/// Discussion Board Member Entity - Implements the user/member business entity requirement for the Actors domain.
///
/// This model stores registered user accounts who can participate in posts and comments, report content, and manage their profile. Maintains strict 3NF normalization: profile data, role assignments, and history are separated into respective tables. For example, the 'discussionboard_member_profiles' entity links here by foreign key for extended details.
///
/// Key relationships: one-to-one/optional with discussionboard_member_profiles, one-to-many with discussionboard_member_histories, and references to role assignment tables. Core for authentication and authorization.
/// Special behaviors: Email must be unique, username must be unique within the platform, soft deletion supported.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_members {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the discussion board member.
  id String @id @db.Uuid

  /// Member's email address - Implements user identification and notification requirements. Used for login and notification triggers. Ensures 3NF: not duplicated elsewhere. For example, 'jane.doe@example.com'. Unique constraint enforced.
  email String

  /// Unique username chosen by the member - Implements the requirement for member identity display and mention system. Not null, unique within system. For example, 'policy_watcher'.
  username String

  /// Hashed password for secure authentication - Directly maps authentication requirement. Enforces normalization: hash stored here only. Value is not the plaintext password. For example, a bcrypt hash string.
  password_hash String

  /// Datetime of account creation - Required for audit trail. Used in user onboarding and compliance logging. Always set at account creation. For example, 2024-07-22T15:15:48+09:00.
  created_at DateTime @db.Timestamptz

  /// Datetime of the most recent update to the member record. Tracks profile/account changes per audit requirements. Updated on any change to member data.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp - Implements platform's right to erasure and retention policy. Null if not deleted; set to deletion time if deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussionboard_audit_logs discussionboard_audit_logs[]
  discussionboard_moderators discussionboard_moderators?
  discussionboard_member_profiles discussionboard_member_profiles?
  discussionboard_member_histories discussionboard_member_histories[]
  discussionboard_threads discussionboard_threads[]
  discussionboard_thread_snapshots discussionboard_thread_snapshots[]
  discussionboard_thread_follows discussionboard_thread_follows[]
  discussionboard_posts discussionboard_posts[]
  discussionboard_post_edit_histories discussionboard_post_edit_histories[]
  discussionboard_post_likes discussionboard_post_likes[]
  discussionboard_post_dislikes discussionboard_post_dislikes[]
  discussionboard_post_reports discussionboard_post_reports[]
  discussionboard_comments discussionboard_comments[]
  discussionboard_comment_edit_histories discussionboard_comment_edit_histories[]
  discussionboard_comment_likes discussionboard_comment_likes[]
  discussionboard_comment_dislikes discussionboard_comment_dislikes[]
  discussionboard_comment_reports discussionboard_comment_reports[]
  discussionboard_reports discussionboard_reports[]
  discussionboard_report_histories discussionboard_report_histories[]
  discussionboard_moderation_actions discussionboard_moderation_actions[]
  discussionboard_bans discussionboard_bans[]
  discussionboard_warnings discussionboard_warnings[]
  discussionboard_appeals_of_appellant_member_id discussionboard_appeals[] @relation("discussionboard_appeals_of_appellant_member_id")
  discussionboard_appeals_of_admin_member_id discussionboard_appeals[] @relation("discussionboard_appeals_of_admin_member_id")
  discussionboard_notifications discussionboard_notifications[]
  discussionboard_notification_preferences discussionboard_notification_preferences[]
  discussionboard_search_histories discussionboard_search_histories[]

  @@unique([email])
  @@unique([username])
  @@index([created_at])
  @@index([deleted_at])
}

/// Discussion Board Moderator Assignment Entity - Implements the role assignment requirement for moderators. 
///
/// This model records which members are assigned moderator rights. Each row represents a member with granted moderator privileges, enforcing permission control and auditability per requirements in 02_discussionboard_user_roles_and_journeys.md. Maintains 3NF by referencing members via foreign key.
///
/// Key relationships: FK to discussionboard_members (each moderator is a member), log of when and by whom the privilege was granted. Used for authorization checks and auditing moderation actions.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_moderators {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for moderator assignment.
  id String @id @db.Uuid

  /// Member's {@link discussionboard_members.id} who is assigned as moderator. Fulfills moderator assignment requirement.
  discussionboard_member_id String @db.Uuid

  /// Admin's {@link discussionboard_admins.id} who granted moderator rights. Fulfills the admin-controlled assignment or revocation of moderator status.
  granted_by_admin_id String @db.Uuid

  /// Datetime when moderator rights were assigned. Required for audit and permission review. For example, 2024-07-22T15:15:48+09:00.
  granted_at DateTime @db.Timestamptz

  /// Datetime moderator rights were revoked (if applicable). Required for tracking ongoing and former moderators. Null if currently moderator.
  revoked_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_moderators_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)
  fk_discussionboard_moderators_admin discussionboard_admins @relation(fields: [granted_by_admin_id], references: [id], onDelete: Cascade)

  @@index([granted_by_admin_id])

  @@unique([discussionboard_member_id])
  @@index([granted_at])
}

/// Discussion Board Admin Entity - Implements admin account business requirement for the Actors domain.
///
/// Stores system-level platform administrators with permissions to manage users, moderators, board configuration, and compliance. Maintains 3NF by separating admin core data from member entity. Used for assignment of roles, escalation handling, platform oversight.
///
/// Key relationships: can be referenced by discussionboard_moderators (as grantor), and linked to audit logs/history for actions.
/// Special behaviors: Unique email per admin, and activity audit trail.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_admins {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the discussion board admin.
  id String @id @db.Uuid

  /// Admin's email address. Implements requirement for admin authentication and notification. Unique among administrators. For example, 'admin@platform.com'.
  email String

  /// Admin username for system login and identification. Implements requirement for admin actions attribution. Unique, non-null within admins only. For example, 'supermod'.
  username String

  /// Hashed password for admin secure authentication. Implements authentication and audit requirements. Value is not plaintext password.
  password_hash String

  /// Datetime of admin account creation. Required for onboarding audit and compliance logging.
  created_at DateTime @db.Timestamptz

  /// Datetime of latest admin profile/account update. For precise audit trail per 3NF.
  updated_at DateTime @db.Timestamptz

  /// Datetime admin account was soft deleted. Null if current; set if removed per retention policy.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussionboard_moderators discussionboard_moderators[]
  discussionboard_policy_updates discussionboard_policy_updates[]

  @@unique([email])
  @@unique([username])
  @@index([created_at])
  @@index([deleted_at])
}

/// Discussion Board Member Profile Entity - Implements the member profile extension requirement from 02_discussionboard_user_roles_and_journeys.md.
///
/// Stores extended profile information (display name, bio, preferences) for each member, separated for normalization and privacy. Maintains strict 3NF; profile details are not stored in core member entity. For example, allows null bio for new accounts, or diverse locales. Used to enrich user experience and for search/discovery features.
///
/// Key relationships: Each profile is tied to a member by 1:1 FK; referenced for displaying user info on posts and comments. Profile can be updated separately from account.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_member_profiles {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for member profile.
  id String @id @db.Uuid

  /// FK to {@link discussionboard_members.id} - the member whose profile this is. Implements 1:1 mapping between member and profile.
  discussionboard_member_id String @db.Uuid

  /// Display name visible on posts/comments. Implements requirement for user-facing identification separate from username. Nullable to support privacy settings.
  display_name String?

  /// Profile bio or introduction text. Implements enrich profile/expression requirement. Nullable for members who do not provide a bio.
  bio String?

  /// Public avatar image link for the member profile. Separate from core account for normalization. Nullable for users without avatars.
  avatar_url String? @db.VarChar(80000)

  /// ISO code for user's UI language/locale setting. For internationalization. Nullable.
  locale String?

  /// User's preferred timezone (IANA tz format, e.g., "Asia/Seoul"). Supports correct timestamp conversion for notifications. Nullable.
  timezone String?

  /// Datetime when the profile was created. Required for audit trail and compliance.
  created_at DateTime @db.Timestamptz

  /// Last profile update time. Tracks modifications, used for search/sorting features.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_member_profiles_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_member_id])
  @@index([created_at])
  @@index([updated_at])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Member History Change/Audit Entity - Implements compliance, audit trail, and profile change history requirements.
///
/// Tracks all significant changes for each member: profile updates, role changes, suspensions, and other actions. Supports platform audit, allows admin to review history. Maintains 3NF by referencing the affected member by FK with no redundant data.
///
/// Key relationships: many-to-one with discussionboard_members (each member has multiple history entries), referenced during compliance reviews.
/// Special behaviors: History is immutable; original event data is always preserved.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_member_histories {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for member history record.
  id String @id @db.Uuid

  /// FK to {@link discussionboard_members.id} - the member whose change history is recorded. Implements requirement for cross-entity audit trails.
  discussionboard_member_id String @db.Uuid

  /// Type of change (e.g., 'profile_update', 'role_granted', 'suspended'). Implements requirement for event categorization and review. Normalized: not repeated elsewhere.
  change_type String

  /// JSON-encoded structured details about the change - Implements additional context for the history event. For example, old/new values in a profile update. Supports audit compliance.
  change_data String

  /// Timestamp when the history entry was created (i.e., when the action occurred). For audit trail and compliance.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_member_histories_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_member_id, created_at])
}

schemas.schema-03-boards.prisma:
/// Board entity - This implements the requirement for organizing discussions by separate boards (see requirements: Introduction, Service Scope, and Core Functional Requirements on board-level categorization). 
///
/// Business explanation: Represents a dedicated board (such as 'General Politics', 'Economics', 'International Affairs') to group threads according to subject or purpose. Supports separation of discussion topics and board-level access control, moderation, and configuration.
/// Maintains 3NF compliance by isolating board attributes from threads/posts. For example, a new 'Elections 2025' board can be created without modifying thread or post tables.
///
/// Key relationships: Will be referenced by thread, post, and moderation policy models in other domains/files. 
/// Special behaviors: Board can be activated/deactivated, may contain links to policies or display features.
///
/// @namespace Boards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_boards {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each board entity.
  id String @id @db.Uuid

  /// Board name - Implements the board labeling requirement. Human-readable title for the board, e.g., 'Global Economy'. Enforces normalization by being atomic (1NF). Example: Shown at top of board view.
  name String

  /// Board description - Implements the requirement for clear labeling and explanation of purpose. Supplies a summary that users see when browsing available boards. Ensures normalization as a direct attribute. Example: 'Discuss world economic trends and data.'
  description String?

  /// Whether the board is currently active/visible. Implements access control requirement. Directly managed by admins. Example: Board may be deactivated during policy reviews.
  is_active Boolean

  /// Creation timestamp - Implements audit logging requirement. Records when the board was established. Ensures integrity for audit purposes. Example: Used in admin logs.
  created_at DateTime @db.Timestamptz

  /// Last updated timestamp for the board (implements audit & compliance requirements). Updated any time board configuration changes. Example: Tracks admin updates to board settings.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussionboard_board_tags discussionboard_board_tags[]
  discussionboard_board_features discussionboard_board_features[]
  discussionboard_threads discussionboard_threads[]

  @@unique([name])
  @@index([is_active])
}

/// Board-level tag entity - Implements the tag taxonomy management requirement for boards (see requirements: Core Functional Requirements, Tagging & Discovery section). 
///
/// Business explanation: Allows boards to be associated with predefined or user-curated tags for improved sorting, searchability, and discovery. Maintains normalized tag assignments; tags may be used for search, recommendations, or access filtering.
/// 3NF compliance is maintained by isolating tag data from boards and other entities.
///
/// Key relationships: Will reference discussionboard_boards (via foreign key). May be referenced by search/index systems. 
/// Special behaviors: Duplicate tag names per board are prevented by composite unique constraint.
///
/// @namespace Boards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_board_tags {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each board tag entry.
  id String @id @db.Uuid

  /// Referenced board's {@link discussionboard_boards.id} - links tag to a specific board. Supports 1:N assignment of tags to boards.
  discussionboard_board_id String @db.Uuid

  /// The tag value (e.g., 'Policy', 'Debate') assigned to this board. Implements tag requirement for cross-board discovery and sorting. Example: Used as filter in board search lists. Normalization: atomic and unique within board context.
  tag String

  /// When this tag was created or assigned to the board. Implements audit and compliance traceability. For example, supports querying recent tag additions.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  board_tag_board_fk discussionboard_boards @relation(fields: [discussionboard_board_id], references: [id], onDelete: Cascade)

  discussionboard_post_tags discussionboard_post_tags[]

  @@unique([discussionboard_board_id, tag])
  @@index([tag])
}

/// Board categorization entity - Implements the requirement for supporting hierarchical or topical categorization of boards (see: Service Scope and Tagging/Discovery requirements). 
///
/// Business explanation: Allows admins to group boards under broader categories (such as 'Politics', 'Economics', 'Society'), enabling multi-board discovery, filtering, and reporting. Maintains 3NF: category metadata is not duplicated within boards.
///
/// Key relationships: Referenced by boards (each board can reference a category), and by reporting modules.
/// Special behaviors: Category names must be globally unique. 
///
/// @namespace Boards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_board_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for board category.
  id String @id @db.Uuid

  /// The display name for the category (e.g., 'Economics', 'Global Affairs'). Implements category organization. Normalization: atomic per category. Used for board filtering and analytics. Example: Shown as section label in board list.
  name String

  /// Textual description of the category. Implements requirements for informative labeling. Example: 'Boards focused on regional and global market issues.' Normalization: atomic, nullable if not needed.
  description String?

  /// Creation timestamp for audit and traceability of board categories.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
