schemas.schema-08-notifications.prisma:
/// Notification delivery record - This implements the notification delivery and tracking requirements from the requirements document (cf. notification mechanisms in core functional requirements and audit requirements). 
///
/// Business purpose: Keeps a persistent, queryable record of every notification (on-site, push, or email) sent to members concerning discussion board updates, replies, moderation outcomes, mentions, and critical policy changes. Ensures members can review notification history, supports audit/compliance logging, and allows for notification status management (delivered/read).
///
/// Normalization: 3NF compliant; notifications are only related to actual events (referenced by IDs), with no redundant/cached values. For example, a notification for a new moderator action would reference the related content without duplicating post/comment content here.
///
/// Key relationships: Will have a foreign key to discussionboard_members (member receiving the notification), and potentially to referenced entities (posts, comments, reports) via their IDs if required—those are soft-foreigns (UUIDs) to allow referencing dynamic business objects.
///
/// Special behaviors: Notifications are immutable records—once sent, status can only be updated (delivered/read), content doesn't change. Used for compliance/audit event trails.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_notifications {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies the notification delivery record.
  id String @id @db.Uuid

  /// Target member's {@link discussionboard_members.id} who is receiving this notification. Ensures referential integrity between notification targets and registered users.
  discussionboard_member_id String @db.Uuid

  /// Type of the notification (e.g., reply, mention, moderation_outcome, warning, policy_update, etc.). Implements requirement for notification categorization by event type. Ensures members can distinguish between notification classes. 3NF compliant by avoiding event duplication.
  type String

  /// Kind of entity this notification references (e.g., post, comment, report, appeal, thread, policy). Implements requirement for referencing specific board objects related to the notification. Keeps this data atomic per 3NF.
  entity_type String

  /// ID of the business object this notification refers to (e.g., ID of a post, comment, report, etc.). Implements cross-entity traceability. Normalized: only contains object reference, not embedded content.
  entity_id String @db.Uuid

  /// Notification message shown to member (short body). Implements business requirement for delivering readable notification content. Normalization: message is tailored for notification but not duplicate of any business content.
  message String

  /// Timestamp when notification was delivered. 3NF: atomic business fact. Used for audit trail and delivery status UI.
  delivered_at DateTime @db.Timestamptz

  /// Timestamp when notification was marked as read by the member. Null if unread. Implements read-status tracking per user, normalized to this entity (not duplicated elsewhere).
  read_at DateTime? @db.Timestamptz

  /// Delivery channel (on_site, email, push, sms, etc). Implements requirement for specifying how notification was sent. Ensures UI can offer opt-out and channel-based filtering. Normalization: atomic value per record.
  channel String

  //----
  // RELATIONS
  //----
  member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_member_id, delivered_at])
  @@index([entity_type, entity_id])
  @@index([message(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Notification preference settings for each member - This implements the requirement to allow members to configure how and for which events they receive notifications, as described in notification mechanism requirements.
///
/// Business purpose: Allows every member to store their notification preferences per notification type and channel (e.g., receive new reply notifications via on-site only, moderate actions by email, mentions by both, etc). Preferences drive notification delivery logic (e.g., block sending if opted out).
///
/// Normalization: 3NF compliance achieved by atomically storing each event type and channel in a preference row, rather than as a denormalized map or structure. For example, storing (member, type, channel, enabled) uniquely for every preference instead of an array keeps redundant data out.
///
/// Key relationships: Each record references the member (discussionboard_members table) whose preference is configured.
///
/// Special behaviors: Application logic ensures that on account deletion, all preferences are removed. Changes here directly affect notification sending at runtime.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_notification_preferences {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies the preference row.
  id String @id @db.Uuid

  /// {@link discussionboard_members.id} of the user whose preferences are being saved. Implements per-user notification customization, as required by the notification delivery and opt-out system. Maintains referential integrity with the member registry.
  discussionboard_member_id String @db.Uuid

  /// Notification type this preference relates to (e.g., reply, mention, moderation_outcome, warning). Implements the event-based preference logic required. Atomic value per 3NF; ensures each row configures exactly one type.
  type String

  /// The delivery channel for this preference ('on_site', 'email', 'push', etc). Implements the requirement for channel-based opt-out and customization. Atomic and 3NF normalized.
  channel String

  /// Whether this member wants to receive this type of notification via this channel. Implements the opt-in/opt-out business requirement for notification personalization. No denormalized/cached flag map, 3NF compliant.
  enabled Boolean

  //----
  // RELATIONS
  //----
  member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_member_id, type, channel])
  @@index([type])
}

schemas.schema-09-search.prisma:
/// Discussion board search index - This implements the search acceleration and full-text search requirement from the requirements document (see discussionboard_core_functional_requirements.md section 6: 'Search, Tagging, & Discovery').
///
/// Business purpose: Facilitates fast retrieval of posts, comments, and associated data for keyword and metadata-based searches, essential for performant user-facing discovery features. This table maintains a normalized, query-efficient structure for the inverted index or summary of searchable entities. Maintains 3NF compliance by separating search optimization data from the main content tables, with all index records strictly referencing the original content by unique identifiers. 
///
/// Usage example: Used when a user searches for keywords, tags, or authors; powers autocomplete, relevance scoring, and result ranking systems.
///
/// Key relationships: Reference to target entities such as posts, comments, threads (by their uuid), and tracking type. No foreign keys in this domain—relations are unidirectional from index towards existing business tables in other components. 
///
/// Special behaviors: Only core normalized index metadata is stored here—no computed ranking or denormalized result summaries allowed (those may be materialized in reporting views if necessary).
///
/// @namespace Search
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_search_indexes {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each search index record.
  id String @id @db.Uuid

  /// Target entity's {@link discussionboard_posts.id}, {@link discussionboard_comments.id}, or other content UUID depending on entity_type.
  entity_id String @db.Uuid

  /// Type of entity referenced by this index record - Implements requirement for polymorphic search indexation (e.g., 'post', 'comment', 'thread'). Ensures normalization by recording only the primary entity type in atomic string format. For example, value 'post' for indexing a post content.
  entity_type String

  /// Aggregated and normalized text used for full-text search - Combines title, body, and metadata fields in a canonical order for indexing. Implements core search requirements (requirement section 6). Stays fully normalized by representing only the atomic, canonical string. For example, concatenated post title and content, or comment body.
  indexed_text String

  /// Timestamp when this index entry was last generated/updated - Implements search freshness and incremental indexing needs. Maintains normalization by being a single timestamp per record. For example, updated whenever the associated entity changes.
  indexed_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  entity discussionboard_posts @relation(fields: [entity_id], references: [id], onDelete: Cascade)

  @@unique([entity_id, entity_type])
  @@index([indexed_at])
  @@index([indexed_text(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Discussion board search histories - This implements the search analytics, audit, and user engagement/tracking requirements (see requirements 'audit & compliance logging' and 'search, tagging & discovery').
///
/// Business purpose: Records members' search actions, including terms searched and contextual metadata for system learning, personalization, and auditing. Maintains 3NF compliance by recording only normalized, atomic search event data. No aggregations or user-calculated fields present.
///
/// Usage example: Used for features like recent search re-surfacing, search analytics, and transparency/audit reporting.
///
/// Key relationships: Optionally references the member performing the search, and records search parameters and timestamps. No direct foreign keys in this table for loose coupling, but 'member_id' is provided as a reference for personalization/audit (references discussionboard_members.id).
///
/// Special behaviors: All data fully normalized; denormalized or aggregated reports must be built in separate materialized views.
///
///
/// @namespace Search
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_search_histories {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each search history event.
  id String @id @db.Uuid

  /// Reference to search-performing member's {@link discussionboard_members.id} - Implements user-specific audit and personalization requirements. No enforced FK constraint for privacy and audit integrity.
  member_id String? @db.Uuid

  /// Raw search query string(s) executed in this event - Implements the requirement for search auditing and analytics. Records the user's exact input, fully normalized as an atomic value per search event.
  search_terms String

  /// Serialized search filters or metadata (e.g., tags, date ranges) - Implements search capability analytics; records in atomic (normalized) format only, never as precomputed lists or aggregates. Example: JSON or CSV with filter parameters.
  search_filters String?

  /// Timestamp when this search was performed - Required by audit, analytics, and for supporting 'recent searches' features. 3NF compliance: single value per row, no rollup.
  performed_at DateTime @db.Timestamptz

  /// Number of results returned for this search event - Implements analytics requirement for search effectiveness, normalized with one row per search event. (May be used for user feedback and reporting.)
  result_count Int @db.Integer

  //----
  // RELATIONS
  //----
  member discussionboard_members? @relation(fields: [member_id], references: [id], onDelete: Cascade)

  @@index([performed_at])
  @@index([member_id, performed_at])
  @@index([search_terms(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-10-policy.prisma:
/// Platform Policy Record - Implements the core platform policy requirements, giving a canonical, versioned record for all operational and behavioral policy rules. Policy data is strictly normalized and auditable, directly mapping to documentation requirements and board policy enforcement. Example: 'Community Guidelines v2.3' issued on a specific date. Integrates with audit logs and is referenced for compliance and moderator review. Only most recent is currently enforced, older remain for trace/audit.
///
/// @namespace Policy
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_policies {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each discussion board policy record.
  id String @id @db.Uuid

  /// Policy title, e.g. 'Community Guidelines' or 'Content Moderation Policy'. Maintains normalization, avoids duplication. Implements document clarity.
  title String

  /// Full text body of the policy, in markdown or rich text. Implements requirement for accessible, canonical platform policy. For example, the text visible to all members or in legal export. Fully normalized: not duplicated in reports/notifications.
  body String

  /// Version or revision string, e.g. 'v2.3'. Tracks updates and historic changes. Enables transparent history/audit. Example: used for date-based policy lookup or regulatory export.
  version String

  /// The date/time when the policy comes into effect. Enables lifecycle and audit tracing. Null when not yet active or for drafts. For example: a policy published for enforcement starting next month.
  effective_at DateTime? @db.Timestamptz

  /// When a policy is superseded or withdrawn. Null if still current. Ensures that only one policy is enforced at a time and supports regulatory retention requirements.
  expired_at DateTime? @db.Timestamptz

  /// Timestamp of policy creation. Satisfies requirements for audit logging.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last update. Ensures audit and policy lifecycle are tracked.
  updated_at DateTime @db.Timestamptz

  /// UUID of the member/moderator/admin who created this policy. Supports audit reporting, foreign key to actors table (exists in other component). Does not duplicate actor data.
  created_by String @db.Uuid

  //----
  // RELATIONS
  //----
  discussionboard_policy_updates discussionboard_policy_updates[]

  @@unique([version])
  @@index([effective_at])
  @@index([expired_at])
  @@index([created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Policy Update/Event Log - Implements transparent policy change and notification history. Records all updates to policies, enabling complete audit/compliance trail. Mapped directly to board transparency, legal, and user-notification requirements. Allows admins/moderators/members to see what was changed, when, and by whom. Enforces 3NF by separating update events/actors from the policy content itself.
///
/// @namespace Policy
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_policy_updates {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each policy update record.
  id String @id @db.Uuid

  /// Target policy being updated. References {@link discussionboard_policies.id}, supporting referential integrity. Key in policy-update history. Maintains normalization in event/audit trails.
  discussionboard_policy_id String @db.Uuid

  /// Actor (admin/moderator/member) making the update (references IDs from respective actors tables—already defined in other components). Normalized and used for audit reporting, does not duplicate actor data.
  actor_id String @db.Uuid

  /// Summary description of what changed and why (for transparency and audit); e.g., 'Clarified spam definition; updated reporting workflow.' 3NF compliance: not embedded in policy or notification structures.
  change_summary String

  /// Event creation timestamp. Satisfies need for sequenced, auditable event logs.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  policy discussionboard_policies @relation(fields: [discussionboard_policy_id], references: [id], onDelete: Cascade)
  updater discussionboard_admins @relation(fields: [actor_id], references: [id], onDelete: Cascade)

  @@index([actor_id])

  @@index([created_at])
  @@index([discussionboard_policy_id])
  @@index([change_summary(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Community Guidelines Canonical Record - Fulfills the need for a canonical, structured storage of community guidelines, versioned with independent lifecycle tracking. Integrates with moderation and onboarding functions. Ensures canonical, up-to-date guidelines are referenceable without duplication. Only currently effective guideline is visible to members; previous versions are preserved for legal and compliance review.
///
/// @namespace Policy
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_community_guidelines {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for community guidelines.
  id String @id @db.Uuid

  /// Guideline section or doc title, e.g. 'Acceptable Use', 'Prohibited Behavior'. Atomic/normalized for search/display.
  title String

  /// Full guideline content, markdown allowed. Canonical, structural, normalized; covers the specific rules detailed for users/moderators/auditors.
  body String

  /// Version/revision tag, e.g. 'v2.0', '2025-07'. Enables traceable guideline life cycle. Normalized: not duplicated in child records.
  version String

  /// When this guideline text becomes authoritative. Enables future-dated guideline publication. Null for not-in-force or draft entries.
  effective_at DateTime? @db.Timestamptz

  /// When this version is retired/superseded; null if active. Enforces policy history/lifecycle business rules.
  expired_at DateTime? @db.Timestamptz

  /// Timestamp when guideline section is created. Audit log compliance and historical integrity.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last change to guideline text. Complete update/audit trail. 3NF: kept atomic to avoid duplicate history.
  updated_at DateTime @db.Timestamptz

  /// UUID of creating admin or member (references ID in actors component). Enables history/audit trace, no actor info duplication.
  created_by String @db.Uuid

  //----
  // RELATIONS
  //----
  @@unique([version])
  @@index([effective_at])
  @@index([expired_at])
  @@index([created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.main.prisma:
generator client {
  provider        = "prisma-client-js"
  previewFeatures = ["postgresqlExtensions", "views"]
  binaryTargets   = ["native"]
}
datasource db {
  provider   = "postgresql"
  url        = env("DATABASE_URL")
  extensions = []
}
